import pathlib,json,html
R=pathlib.Path(__file__).resolve().parent
S=json.loads((R/'phase_b_summary.json').read_text())
sections=[];table=[]
for key,title,note in [('round3','Round 3 · primary','160 frozen texts'),('round2_rerun','Round 2 · regression check','120 texts; failures informed v7 development')]:
 s=S[key];bars=[]
 for k,label in [('ours','Ours'),('zerogpt','ZeroGPT')]:
  q=s['quality'][k];tip=html.escape(f'{title} / {label}: {q:.4f} out of 10')
  bars.append(f'<div class="bar {k}" tabindex="0" aria-label="{tip}"><i style="width:{q*10:.6f}%"></i><span>{label} <strong>{q:.2f}</strong></span><b class="tip">{tip}</b></div>')
  c=s['categories'];h=c['human_native']['n']+c['human_non_native']['n'];tn=h-c['human_native'][k]['flagged']-c['human_non_native'][k]['flagged']
  table.append(f'<tr><td>{title} / {label}</td><td>{tn}/{h}</td><td>{c["ai_raw"][k]["flagged"]}/{c["ai_raw"]["n"]}</td><td>{c["ai_casual_or_humanized"][k]["flagged"]}/{c["ai_casual_or_humanized"]["n"]}</td></tr>')
 sections.append('<div class="row"><div><strong>'+title+'</strong><p>'+note+'</p></div><div class="pair">'+''.join(bars)+'</div></div>')
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detector Quality Comparison</title><style>
:root{--surface:#fcfcfb;--ink:#0b0b0b;--subink:#52514e;--series-ours:#2a78d6;--series-zero:#eb6834;--grid:#e1e0d9}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--surface:#1a1a19;--ink:#f0efec;--subink:#c3c2b7;--series-ours:#3987e5;--series-zero:#d95926;--grid:#383835;color-scheme:dark}}
:root[data-theme="dark"]{--surface:#1a1a19;--ink:#f0efec;--subink:#c3c2b7;--series-ours:#3987e5;--series-zero:#d95926;--grid:#383835;color-scheme:dark}
*{box-sizing:border-box}section{font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,var(--ink));display:grid;gap:18px;min-width:0}p{margin:2px 0 0;color:var(--muted-foreground,var(--subink));font-size:12px}.controls{display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:space-between}.legend{display:flex;gap:20px}.legend i{display:inline-block;width:10px;height:10px;background:var(--series-ours);margin-right:6px}.legend .zero{background:var(--series-zero)}button{background:var(--card,var(--surface));color:inherit;border:1px solid var(--border,var(--grid));border-radius:4px;padding:4px 8px;cursor:pointer}.row{display:grid;grid-template-columns:minmax(110px,1fr) minmax(140px,1.8fr);align-items:center;gap:18px}.pair{display:grid;gap:4px}.bar{position:relative;height:38px;border-left:1px solid var(--border,var(--grid));display:flex;align-items:flex-end;padding-left:5px;font-size:13px}.bar i{position:absolute;left:0;top:0;height:10px;border-radius:0 4px 4px 0;background:var(--series-ours)}.zerogpt i{background:var(--series-zero)}.bar:focus-visible{outline:2px solid var(--ring,var(--series-ours));outline-offset:2px}.bar:hover i,.bar:focus i{filter:brightness(1.15)}.tip{display:none;position:absolute;z-index:2;right:0;bottom:40px;background:var(--popover,var(--surface));color:var(--foreground,var(--ink));padding:6px 8px;border:1px solid var(--border,var(--grid));border-radius:4px;font:12px/1.4 var(--font-sans,system-ui);max-width:100%}.bar:hover .tip,.bar:focus .tip{display:block}.axis{display:flex;justify-content:space-between;font:11px var(--font-mono,monospace);color:var(--muted-foreground,var(--subink));border-top:1px solid var(--border,var(--grid));padding-top:5px}.note{font-size:12px;color:var(--muted-foreground,var(--subink));max-width:75ch}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:6px;border-bottom:1px solid var(--border,var(--grid));font-variant-numeric:tabular-nums}summary{cursor:pointer}.textures .zerogpt i{background-image:repeating-linear-gradient(135deg,transparent 0 3px,var(--ink) 3px 4px)}
@media(max-width:430px){.row{grid-template-columns:1fr;gap:7px}}@media print,(forced-colors:active){.zerogpt i{background-image:repeating-linear-gradient(135deg,transparent 0 3px,var(--ink) 3px 4px)}}
</style></head><body><section id="scores" aria-label="Fixed quality scores"><div class="controls"><div class="legend"><span><i></i>Ours</span><span><i class="zero"></i>ZeroGPT</span></div><button aria-pressed="false" onclick="const s=document.getElementById('scores');s.classList.toggle('textures');this.setAttribute('aria-pressed',s.classList.contains('textures'))">Toggle texture</button></div>'''+''.join(sections)+'''<div class="row"><span></span><div class="axis"><span>0</span><span>Quality score · higher is better</span><span>10</span></div></div><p class="note">Fixed formula: 40% human specificity + 20% raw-AI sensitivity + 40% casual/humanized-AI sensitivity, multiplied by 10. AI-polished human excluded. ZeroGPT answers are reused, not re-queried.</p><details><summary>Exact score components</summary><div class="table-wrap"><table><thead><tr><th>Set / detector</th><th>Humans correct</th><th>Raw caught</th><th>Hard caught</th></tr></thead><tbody>'''+''.join(table)+'''</tbody></table></div></details></section></body></html>'''
(R/'phase_b_comparison.html').write_text(page)
print('Wrote phase_b_comparison.html')
